// Bots follow oval with paced speed
bots.forEach((b,i)=>{b.progress+=(.105+i*.006)*dt*(.92+Math.sin(performance.now*.001+i)*.08);const t=Math.PI/2-b.progress,bp=ellipsePoint(t);b.x+= (bp.x-b.x)*.16;b.y+=(bp.y-b.y)*.16;b.a=Math.atan2(bp.y-b.y,bp.x-b.x);});

// Lap detection: pass the start line in the clockwise direction while on the road.
const pAngle=Math.atan2((player.y-H*.53)/(H*.32),(player.x-W*.5)/(W*.39));
const normalized=(pAngle-Math.PI/2+Math.PI*2)%(Math.PI*2);
if(player.v>15 && normalized<.32 && roadAt(player.x,player.y) && player.w>1.1){
  lap=Math.min(3,lap+1); player.w=0;
  lapEl.textContent=lap;
  if(lap>=3){
    finished=true; const elapsed=(performance.now()-raceStart)/1000;
    result.textContent='FINISH!'; timeEl.textContent='Time '+String(Math.floor(elapsed/60)).padStart(2,'0')+':'+(elapsed%60).toFixed(3).padStart(6,'0'); overlay.style.display='grid';
  }
}
if(normalized>1.0)player.w=Math.max(player.w,.0+.1); else player.w=normalized;
lapEl.textContent=lap; speedEl.textContent=Math.round(Math.abs(player.v)*.72);

